INSERT INTO profile (id,name,role,description,tagline,location,avatar,cv,phone,show_phone) VALUES (1,'Silvia Agustina Banegas','Estudiante de Informática / Desarrolladora Web','Soy estudiante de informática, interesada en el desarrollo web, los sistemas y la creación de soluciones tecnológicas. Me gusta aprender nuevas herramientas, resolver problemas y participar en proyectos donde pueda combinar programación, diseño y organización.','Aprendiendo, creando y desarrollando una idea a la vez.','Mar del Plata, Buenos Aires, Argentina.','','','',false);
INSERT INTO experiences (title,organization,status,description,date,display_order) VALUES ('Desarrolladora Web - Prácticas Profesionalizantes','Grupo Núcleo','Actualidad','Participación en prácticas profesionalizantes orientadas al desarrollo de soluciones web para Grupo Núcleo, trabajando en proyectos reales y aplicando conocimientos de frontend, backend, bases de datos, APIs e integración de servicios.','',0);
